UPDATE projects SET images = '["https://tofmglzhxvdozgnwmvhb.supabase.co/storage/v1/object/public/images/gold-gym-sector-67-lounge-design.webp","https://tofmglzhxvdozgnwmvhb.supabase.co/storage/v1/object/public/images/gold-gym-sector-67-cardio-design.webp","https://tofmglzhxvdozgnwmvhb.supabase.co/storage/v1/object/public/images/gold-gym-sector-67-fitness-floor-design.webp","https://tofmglzhxvdozgnwmvhb.supabase.co/storage/v1/object/public/images/gold-gym-sector-67-strength-floor-design.webp","https://tofmglzhxvdozgnwmvhb.supabase.co/storage/v1/object/public/images/gold-gym-sector-67-functional-zone-design.webp","https://tofmglzhxvdozgnwmvhb.supabase.co/storage/v1/object/public/images/gold-gym-sector-67-corridor-design.webp","https://tofmglzhxvdozgnwmvhb.supabase.co/storage/v1/object/public/images/gold-gym-sector-67-washroom-design.webp"]' WHERE slug = 'gold-gym';
SELECT (SELECT count(*) FROM projects) AS projects, (SELECT count(*) FROM blog_posts) AS blog_posts, (SELECT count(*) FROM storage.objects WHERE bucket_id = 'images') AS recovered_images, (SELECT count(*) FROM pg_tables WHERE schemaname = 'public' AND rowsecurity) AS protected_tables;
